import {art,character} from './art.js';
import {chapters,nodes,endings,freshState,choose,interpolate} from './story.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',book:'<path d="M12 5v15M12 5Q6 2 2 4v15q5-2 10 1 5-3 10-1V4q-4-2-10 1Z"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5Zm4 4q4 4 0 8m3-11q7 7 0 14"/>',mute:'<path d="m11 4-6 5H2v6h3l6 5Zm5 5 6 6m0-6-6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',check:'<path d="m5 12 4 4L20 5"/>',heart:'<path d="M12 21 3 12C-3 5 7-1 12 6c5-7 15-1 9 6Z"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.star}</svg>`;
const avatar=(who)=>`<svg viewBox="-80 -100 160 170" aria-hidden="true">${character(who)}</svg>`;
const SAVE='color-caper-save-v1',COLLECTION='color-caper-endings-v1',SOUND='color-caper-sound-v1';
let storageOK=true;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageOK=false;return false;}}
function validSave(s){return s&&s.version===1&&(nodes[s.node]||(s.node==='ending'&&endings[s.end]))&&['blob','zip'].includes(s.companion)&&['heart','spark','guts'].every(k=>Number.isInteger(s.traits?.[k])&&s.traits[k]>=0&&s.traits[k]<100)&&Array.isArray(s.flags)&&s.flags.every(x=>typeof x==='string')&&Array.isArray(s.items)&&s.items.every(x=>typeof x==='string')&&Array.isArray(s.trail)&&s.trail.every(x=>typeof x?.node==='string'&&typeof x?.label==='string');}
let saved=read(SAVE,null),state=validSave(saved)?saved:null;
let collected=read(COLLECTION,[]);collected=Array.isArray(collected)?collected.filter(id=>endings[id]):[];
let sound=read(SOUND,false)===true,view='cover',puzzleSelection=[],puzzleSolved=false,puzzleFeedback='',toastTimer,audio;
function ping(success=false){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const notes=success?[392,494,587]:[440];notes.forEach((n,i)=>{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.08;o.type='sine';o.frequency.setValueAtTime(n,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.08,t+.01);g.gain.exponentialRampToValueAtTime(.0001,t+.18);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.2);});}catch{sound=false;write(SOUND,false);}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function header(){return `<header class="topbar"><button class="brand" data-action="cover" aria-label="The Great Color Caper home">${icon('star')}<span><strong>DOODLEBURG</strong><small>A LITTLE WORLD OF WHAT-IFS</small></span></button><nav class="nav" aria-label="Main navigation">${view==='cover'?'<button class="text-btn desktop-link" data-action="crew">Meet the misfits</button>':'<button class="text-btn desktop-link" data-action="cover">'+icon('back')+'Cover</button>'}<button class="text-btn desktop-link" data-action="help">How to play</button><button class="pill" data-action="journal">${icon('book')}<span>Scrapbook</span></button><button class="pill" data-action="sound" aria-pressed="${sound}" aria-label="Sound effects ${sound?'on':'off'}. Toggle sound effects.">${icon(sound?'sound':'mute')}<span>${sound?'On':'Off'}</span></button></nav></header>`;}
function cover(){return `<main id="main" class="cover"><section class="hero" aria-labelledby="cover-title"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> ISSUE 01 &nbsp; / &nbsp; A PLAYABLE COMIC</div><h1 class="title" id="cover-title"><span class="little">THE GREAT</span><span class="color">COLOR</span><span class="caper">CAPER<span class="sparkle">✦</span></span></h1><p class="tagline">One tiny town. One grumpy eraser.<br>A whole lot of oops.</p><p class="desc">The colors have gone missing. The heroes are wildly unqualified. And you? You get to decide what happens next.</p><div class="hero-actions"><button class="button pink" data-action="${state?'resume':'start'}">${state?(state.end?'REVISIT YOUR ENDING':'CONTINUE YOUR CAPER'):"LET’S MAKE A MESS"}${icon('arrow')}</button>${state?'<button class="text-btn" data-action="restart">Start a new story</button>':''}</div><p class="tiny-note">${icon('check')} ${state?'Your adventure is waiting right here.':'No downloads. No perfect choices. Just play.'}</p></div><div class="hero-art"><div class="comic-frame">${art('cover',{bubble:'A very bad day|to be a rainbow.'})}</div><div class="sticker">YOUR CHOICES<br>DRAW THE<br>STORY ↗</div><span class="corner-tag">A SMALL CREW. A BIG, COLORFUL MESS.</span></div></section><div class="issue-strip"><span>${icon('clock')} About 15–20 minutes</span><span>${icon('book')} 5 little chapters</span><span>${icon('star')} 4 possible endings</span><span class="note">Made for your inner kid. And your outer one.</span></div><section id="crew" aria-labelledby="crew-title"><div class="crew-heading"><h2 id="crew-title">Meet your fellow misfits.</h2><span class="handnote">Not exactly superheroes.<br>That’s kind of the point. ↙</span></div><div class="crew-grid"><article class="crew-card"><div class="avatar">${avatar('pip')}</div><div><small>THE ACCIDENTAL HERO</small><h3>Pip. That’s you!</h3><p>A tiny crayon with a big heart. Slightly outside the lines.</p></div></article><article class="crew-card"><div class="avatar">${avatar('blob')}</div><div><small>THE SQUISHY OPTIMIST</small><h3>Good ol’ Bloop.</h3><p>Part paint. Part feelings. Fully here for the snacks.</p></div></article><article class="crew-card"><div class="avatar">${avatar('zip')}</div><div><small>THE STICK-TO-IT FRIEND</small><h3>Zip to the rescue.</h3><p>Has a plan for everything. And tape for everything else.</p></div></article></div></section><footer class="cover-footer"><span>For anyone who’s ever felt a little outside the lines.</span><span><strong>Made by samidun</strong><br>Best enjoyed with a little curiosity.</span></footer></main>`;}
function chapterBar(ch){return `<nav class="chapter-bar" aria-label="Story progress">${chapters.map((name,i)=>`<div class="chapter-step ${i===ch?'current':i<ch?'done':''}" ${i===ch?'aria-current="step"':''}><b>${i<ch?'✓':i+1}</b><span>${name}</span></div>`).join('')}</nav>`;}
function puzzleMarkup(p){return `<section class="puzzle" aria-labelledby="puzzle-title"><h2 id="puzzle-title">${p.kind==='mix'?'Mix a little magic.':'Put the pieces in order.'}</h2><div class="puzzle-controls">${p.items.map(v=>`<button class="tile" data-pick="${esc(v)}" ${puzzleSelection.includes(v)||puzzleSolved?'disabled':''}>${p.kind==='mix'?`<span class="swatch" style="--swatch:${{Red:'#ed8a80',Yellow:'#ffdb52',Blue:'#81b8dc'}[v]}"></span>`:''}${esc(v)}</button>`).join('')}</div><div class="puzzle-slots" aria-label="Your selection">${Array.from({length:p.answer.length},(_,i)=>`<span class="slot">${puzzleSelection[i]?esc(puzzleSelection[i]):i+1+' · · ·'}</span>`).join('')}</div><div aria-live="polite" class="puzzle-message ${puzzleSolved?'success':''}">${esc(puzzleFeedback)}</div>${puzzleSolved?`<button class="button small" data-action="puzzle-next">Turn the page ${icon('arrow')}</button>`:`<div class="puzzle-bottom"><button class="text-btn" data-action="puzzle-reset">Start again</button><button class="button small" data-action="puzzle-check" ${puzzleSelection.length!==p.answer.length?'disabled':''}>${p.kind==='mix'?'Mix colors':'Try the order'} ${icon('arrow')}</button></div><details class="hint"><summary>A little nudge?</summary><p>${p.hint}</p></details>`}</section>`;}
function game(){const n=nodes[state.node];return `<main id="main" class="game">${chapterBar(n.chapter)}<div class="reader"><div class="scene-column"><div class="panel-label"><span>DOODLEBURG / ${esc(n.scene.toUpperCase())}</span><span>PANEL ${String(state.trail.length+1).padStart(2,'0')}</span></div><div class="scene-frame">${art(n.scene,{gray:n.gray,bubble:n.bubble,companion:state.companion})}</div><div class="scene-foot"><div class="buddy-tag">${avatar(state.companion)}<span><strong>${state.companion==='blob'?'Bloop':'Zip'} has your back.</strong>Even when things get a little weird.</span></div><div class="read-tip">Take your time.<br>The story waits for you.</div></div></div><article class="story-content"><div class="eyebrow">CHAPTER ${n.chapter+1} / ${esc(chapters[n.chapter])}</div><h1 tabindex="-1" id="scene-title">${esc(n.title)}</h1><div class="narrative">${n.text.map(p=>`<p>${esc(interpolate(p,state))}</p>`).join('')}</div>${n.puzzle?puzzleMarkup(n.puzzle):`<div class="choices">${n.choices.length>1?'<p class="choice-label">WHAT DO YOU DO?</p>':''}${n.choices.map((c,i)=>{const locked=c.requires&&state.traits[c.requires]<c.min;return `<button class="choice" data-choice="${i}" ${locked?'disabled':''}><span class="number">${locked?'✧':n.choices.length===1?'→':i+1}</span><span><strong>${esc(c.label)}</strong><small>${locked?'Try more playful ideas on another adventure to unlock this.':esc(c.hint)}</small></span><span class="arrow" aria-hidden="true">↗</span></button>`;}).join('')}</div>`}</article></div><footer class="reader-bottom"><span>${icon('check')}${storageOK?'Saved on this browser after each page.':'Browser storage is unavailable. Keep this tab open.'}</span><button class="text-btn" data-action="help">A little help?</button><span class="desktop-link">${n.puzzle?'No wrong turns. Just another try.':'Your choices leave little ripples.'}</span></footer></main>`;}
function ending(){const e=endings[state.end];return `<main id="main" class="game">${chapterBar(4)}<div class="reader end-reader"><div class="scene-column"><div class="panel-label"><span>YOUR STORY, BEAUTIFULLY IMPERFECT</span><span>THE END… FOR NOW.</span></div><div class="scene-frame">${art('ending',{bubble:e.bubble,ending:state.end})}</div><div class="ending-count"><span>${icon('star')}</span><span>${collected.length} of 4 endings discovered</span><button class="text-btn" data-action="journal">See scrapbook ↗</button></div></div><article class="story-content"><span class="ending-banner">${e.kicker}</span><h1 tabindex="-1" id="scene-title">${e.title}</h1><div class="narrative">${e.text.map(p=>`<p>${p}</p>`).join('')}</div><p class="tiny-note">Your choices made this version of Doodleburg.</p><div class="end-buttons"><button class="button pink" data-action="restart">Another little adventure ${icon('arrow')}</button><button class="button white" data-action="cover">Back to the cover</button></div><details class="recap"><summary>The choices that brought you here</summary><ol>${state.trail.filter(t=>nodes[t.node]?.choices?.length>1).map(t=>`<li>${esc(t.label)}</li>`).join('')}</ol></details></article></div></main>`;}
function render(focus=false){$('#app').innerHTML=header()+(view==='cover'?cover():state.end?ending():game());if(focus){window.scrollTo({top:0,behavior:'instant'});$('#scene-title')?.focus({preventScroll:true});}}
function newGame(){state=freshState();write(SAVE,state);view='game';puzzleSelection=[];puzzleSolved=false;puzzleFeedback='';render(true);ping();}
function advance(choice){if(choice.requires&&state.traits[choice.requires]<choice.min)return;state=choose(state,choice);if(state.end&&!collected.includes(state.end)){collected.push(state.end);write(COLLECTION,collected);}write(SAVE,state);puzzleSelection=[];puzzleSolved=false;puzzleFeedback='';render(true);ping(!!state.end);if(choice.item)toast('Tucked into your scrapbook: '+choice.item);else if(choice.companion)toast((choice.companion==='blob'?'Bloop':'Zip')+' is very glad you asked.');else if(choice.flag&&choice.trait)toast({heart:'A little kindness leaves a mark.',spark:'A strange little idea takes root.',guts:'Your crew feels a little braver.'}[choice.trait]);}
let dialogReturnFocus;
function modal(title,content){dialogReturnFocus=document.activeElement;const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="close-btn" data-action="close" aria-label="Close dialog">×</button></div><div class="dialog-body">${content}</div>`;d.showModal();}
function journal(){modal('Your little scrapbook.',`<p>Things you noticed. Friends you made. Endings that are entirely yours.</p><h3>Pocket-sized discoveries</h3>${state?.items.length?`<div class="item-list">${state.items.map(item=>`<span class="item">${esc(item)}</span>`).join('')}</div>`:'<p class="empty-note">A fresh page! Follow your curiosity to collect clues as you play.</p>'}<h3>The ending collection · ${collected.length}/4</h3><div class="ending-grid">${Object.entries(endings).map(([id,e],i)=>`<div class="ending-card ${collected.includes(id)?'':'locked'}"><small>${collected.includes(id)?'DISCOVERED ✓':'STILL A LITTLE MYSTERY'}</small><h4>${collected.includes(id)?e.title:'Ending '+(i+1)+' · ? ? ?'}</h4><p>${collected.includes(id)?e.kicker.replace('THE ','').toLowerCase():'A different choice. A different ripple.'}</p></div>`).join('')}</div><p class="tiny-note">Saved on this browser. New adventures keep your ending collection.</p>`);}
function help(){modal('A little help for a big caper.',`<p><strong>Read, look around, and choose.</strong> Tap an answer to turn the page. On a keyboard, use Tab and Enter, or number keys 1–3 for story choices.</p><p>There are five chapters, three gentle puzzles, and four endings. Earlier decisions help shape the finale. You can retry every puzzle, and “A little nudge?” reveals a hint.</p><p>Your page and discoveries save automatically on this browser. Return to the cover and choose <strong>Continue your caper</strong> whenever you like. Clearing browser data clears your progress.</p><p>Sound effects start off. Use the sound button to add little musical pops. Motion follows your device’s reduced-motion preference.</p><p>Expect roughly 15–20 minutes if you linger over the story and puzzles. There is no timer. Take as long as you like.</p>`);}
function action(name){switch(name){case'cover':view='cover';render();window.scrollTo({top:0,behavior:'instant'});break;case'crew':$('#crew').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});break;case'start':newGame();break;case'resume':view='game';render(true);break;case'sound':sound=!sound;write(SOUND,sound);const b=$('[data-action="sound"]');b.setAttribute('aria-pressed',sound);b.setAttribute('aria-label',`Sound effects ${sound?'on':'off'}. Toggle sound effects.`);b.innerHTML=icon(sound?'sound':'mute')+`<span>${sound?'On':'Off'}</span>`;ping();break;case'journal':journal();break;case'help':help();break;case'close':$('#dialog').close();break;case'restart':modal('A fresh page?',`<p>Start again from the beginning? Your current adventure will be replaced. Every ending you have discovered stays in your scrapbook.</p><div class="dialog-actions"><button class="button pink" data-action="confirm-restart">Yes, a new adventure ${icon('arrow')}</button><button class="button white" data-action="close">Keep this one</button></div>`);break;case'confirm-restart':$('#dialog').close();newGame();break;case'puzzle-reset':puzzleSelection=[];puzzleFeedback='';refreshPuzzle();break;case'puzzle-check':checkPuzzle();break;case'puzzle-next':advance({label:'Solved: '+nodes[state.node].title,next:nodes[state.node].puzzle.next});break;}}
function refreshPuzzle(focusAction){const p=nodes[state.node].puzzle;$('.puzzle').outerHTML=puzzleMarkup(p);if(focusAction)$(`[data-action="${focusAction}"]`)?.focus({preventScroll:true});}
function checkPuzzle(){const p=nodes[state.node]?.puzzle;if(!p||puzzleSelection.length!==p.answer.length||puzzleSolved)return;const right=p.kind==='mix'?p.answer.every(v=>puzzleSelection.includes(v)):p.answer.every((v,i)=>puzzleSelection[i]===v);puzzleSolved=right;puzzleFeedback=right?p.success:p.kind==='mix'?'A lovely color, but not green yet. Start again, or peek at the hint.':'The lock gives a friendly wobble. Not quite! Start again, or peek at the hint.';refreshPuzzle(right?'puzzle-next':'puzzle-reset');ping(right);}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;if(b.dataset.action){action(b.dataset.action);return;}if(b.dataset.choice!==undefined&&view==='game'&&!state.end){const c=nodes[state.node]?.choices?.[Number(b.dataset.choice)];if(c)advance(c);}if(b.dataset.pick&&view==='game'){const p=nodes[state.node]?.puzzle,v=b.dataset.pick;if(p&&!puzzleSolved&&p.items.includes(v)&&!puzzleSelection.includes(v)&&puzzleSelection.length<p.answer.length){puzzleSelection.push(v);refreshPuzzle(puzzleSelection.length===p.answer.length?'puzzle-check':undefined);if(puzzleSelection.length<p.answer.length)$('.tile:not(:disabled)')?.focus({preventScroll:true});ping();}}});
document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||$('#dialog').open||view!=='game'||state.end||!['1','2','3'].includes(e.key))return;const c=nodes[state.node]?.choices?.[Number(e.key)-1];if(c){e.preventDefault();advance(c);}});
$('#dialog').addEventListener('close',()=>{if(dialogReturnFocus?.isConnected)dialogReturnFocus.focus();});
render();
